          "하나씩 살펴볼게요. 이지엔6프로연질캡슐 10캡슐은 자체 수집 기준가로 1600원이에요. 캡슐 하나당 계산하면 160원 정도인 셈이라 낱개 부담은 크지 않은 편이죠. 다만 판매처마다 실제 가격은 조금씩 달라질 수 있어요.\n\n같은 성분인 덱시부프로펜 제제는 여러 제약사에서 나오고 있어서, 성분과 함량이 같다면 효과 차이보다는 캡슐 크기나 코팅 같은 복용감 차이가 더 크게 느껴질 수 있어요. 여러 곳을 일일이 비교하기보다는 아래 버튼에서 현재 가격을 바로 확인하는 게 가장 빠른 방법이에요.\n\n1회 300mg씩 하루 2~4회, 최대 1200mg까지 쓰는 게 임상시험과 식약처 허가사항으로 확인된 기준이라 캡슐당 가격을 알아두면 하루 복용 비용을 가늠하기 쉬워요. 10캡슐에 1600원, 낱개로 160원이라는 가격도 이 기준 안에서 나온 셈이에요. 무리하게 아끼려 들지 마세요.",
