          "15세 이상 성인 기준으로 1회 2정씩 1일 3회 복용하는 약이고요. 정해진 복용 횟수를 넘기지 않아야 해요.\n\n식약처 허가사항에는 공복을 피해서 복용하라고 되어 있어요. 위장 자극을 줄이기 위해서죠. 생리통으로 속이 예민해진 상태라면 더 신경 써야 할 부분이에요. 복용 간격도 4시간 이상 유지해야 하니까, 아침·점심·저녁 식후처럼 시간을 정해두고 먹는 게 편해요. 앞당기면 안 돼요. 통증이 남았다고 다음 복용 시간을 임의로 당기지 말고, 정해진 간격을 그대로 지켜야 해요.\n\n보관은 습기와 빛을 피해 실온에 두고, 어린이 손이 닿지 않는 곳에 두는 것도 잊지 마세요. 정해진 용법과 용량을 지키는 게 가장 중요하다고 허가 기준에도 강조돼 있어요. 깜빡했다면 다음 번에 두 배로 먹지 마세요. 원래 정해진 양만 그대로 이어서 드시면 돼요.",
