        content: "훼라민큐의 핵심 성분은 감마오리자놀(γ-Oryzanol)이에요. 감마오리자놀은 쌀겨에서 추출한 천연 성분으로 식물성 스테롤과 페룰산 에스테르의 혼합물이에요. 자율신경계에 작용해 열감·발한·불안 등 갱년기 자율신경 증상 완화에 도움을 준다고 알려져 있어요.\n\n인삼건조엑스(Ginseng)는 신체 피로 회복, 면역 기능 개선, 스트레스 저항력 향상에 도움을 줘요. 갱년기의 피로·무기력증 완화에 기여해요. 비타민 B6는 신경전달물질 합성에 필요한 조효소로 갱년기 감정 기복·우울감 완화를 지원해요.\n\n기타 첨가제로는 정제 기제인 유당수화물, 활택제인 스테아르산마그네슘이 포함되어 있어요.",
